public class StaticFailureDemo {
    static class Broken {
        static { if(Boolean.parseBoolean("true")) throw new RuntimeException("boom"); }
    }
    public static void main(String[] args){
        try { Class.forName(Broken.class.getName()); }
        catch(Throwable failure){ System.out.println(failure.getClass().getSimpleName()); }
    }
}
